mapper.select:
SELECT p.id, p.user_id, u.nickname AS author_nickname, u.avatar AS author_avatar, p.post_type, p.title, p.title_en, p.summary, p.cover_img, p.view_count, p.like_count, p.comment_count, p.status, p.create_time FROM ugc_post p LEFT JOIN sys_user u ON p.user_id = u.id WHERE p.deleted = 0 AND p.status = 1
AND p.post_type = #{postType}
ORDER BY p.create_time DESC LIMIT #{offset}, #{size}
